import sys
from collections import defaultdict, deque

def bfs(start, graph):
    queue = deque([start])
    visited = {start}
    distances = {start: 0}
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                distances[neighbor] = distances[node] + 1
                queue.append(neighbor)
    return distances

def find_path_distances(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    distances = [None] * (n + 1)
    for i in range(1, n + 1):
        distances[i] = bfs(i, graph)
    return distances

def can_paint_edges(n, edges, ants):
    distances = find_path_distances(n, edges)
    results = []
    for a, b, c, d in ants:
        ab_distance = distances[a][b]
        ac_distance = distances[a][c]
        ad_distance = distances[a][d]
        bc_distance = distances[b][c]
        bd_distance = distances[b][d]
        cd_distance = distances[c][d]
        if (ab_distance + cd_distance == ac_distance + bd_distance) or (ab_distance + bc_distance == ad_distance + cd_distance):
            results.append('1')
        elif (ac_distance + bd_distance == ab_distance + cd_distance) or (ac_distance + cd_distance == ad_distance + bc_distance):
            results.append('2')
        else:
            return 'NO'
    return 'YES\n' + '\n'.join(results)

input = sys.stdin.read().split()
n = int(input[0])
edges = [(int(input[i]), int(input[i + 1])) for i in range(1, 2 * n - 1, 2)]
m = int(input[2 * n - 1])
ants = [(int(input[i]), int(input[i + 1]), int(input[i + 2]), int(input[i + 3])) for i in range(2 * n, 2 * n + 4 * m, 4)]

print(can_paint_edges(n, edges, ants))
